export default [
{
  slug: "registered-nurse", title: "Registered Nurse", short: "RN", cat: "healthcare",
  aka: ["RN", "Staff Nurse", "Bedside Nurse", "Clinical Nurse"],
  blurb: "Assess patients, give treatments, coordinate care and educate families.",
  summary: "Registered nurses (RNs) assess patients, plan and deliver nursing care, give medications and treatments, monitor for changes, and educate patients and families — in hospitals, clinics, schools, home health and many other settings.",
  overview: [
    "Registered nurses are the backbone of patient care. They perform head-to-toe assessments, administer medications and IV therapies, monitor vital signs and lab results, coordinate with physicians and other team members, and teach patients how to manage their conditions after they go home.",
    "To become an RN you must earn an associate degree in nursing (ADN) or a bachelor of science in nursing (BSN) and pass the NCLEX-RN licensing exam. The field offers enormous variety — emergency, ICU, pediatrics, labor and delivery, oncology, school nursing and more — and a clear path to advanced practice roles such as nurse practitioner."
  ],
  duties: ["Assess patients’ physical and emotional condition and record observations", "Administer medications, IV fluids and treatments as ordered", "Monitor patients, interpret vital signs and lab values and recognize deterioration", "Develop and update nursing care plans", "Coordinate care with physicians, therapists, case managers and families", "Educate patients and families about diagnoses, medications and self-care", "Supervise LPNs and nursing assistants and delegate tasks appropriately"],
  day: [["6:45 AM", "Receive bedside handoff on five medical-surgical patients and check new orders and overnight labs."], ["7:30 AM", "Complete head-to-toe assessments and prioritize: one patient has a rising heart rate and new shortness of breath."], ["8:30 AM", "Run the morning medication pass, hang an IV antibiotic and check a potassium level before giving a diuretic."], ["10:00 AM", "Call the physician using SBAR about the deteriorating patient and carry out new orders for labs and a chest X-ray."], ["12:00 PM", "Teach a newly diagnosed diabetic patient how to check blood sugar and give insulin, using teach-back."], ["2:30 PM", "Prepare a discharge: reconcile medications, arrange home health and review warning signs with the family."], ["6:45 PM", "Chart reassessments, update care plans and give a thorough handoff to the night nurse."]],
  env: "About half of RNs work in hospitals; others work in physician offices, home health, nursing homes, outpatient and ambulatory surgery centers, schools, government and the military. Hospital nursing involves long periods on your feet, lifting and exposure to infectious disease.",
  schedule: "Hospitals run around the clock, so nurses often work 12-hour shifts, three days a week, including nights, weekends and holidays. Clinics and schools usually keep daytime hours.",
  pros: ["Strong pay, with a median near six figures", "Huge variety of specialties and settings", "High demand nearly everywhere in the U.S.", "Clear path to advanced practice, leadership and education"],
  cons: ["Demanding education and a rigorous licensing exam", "Physically and emotionally exhausting shifts", "Nights, weekends and holidays are common early on", "High responsibility — errors can harm patients"],
  hard: ["Patient assessment", "Medication administration and dosage calculation", "IV therapy", "Care planning and documentation", "Recognizing clinical deterioration", "Patient education"],
  soft: ["Critical thinking", "Compassion and emotional resilience", "Clear communication under pressure", "Prioritization and delegation"],
  tools: ["Electronic health records such as Epic or Cerner", "IV infusion pumps", "Cardiac monitors and telemetry", "Glucometers and point-of-care testing", "Barcode medication administration scanners", "Automated dispensing cabinets"],
  edu: "You need an associate degree in nursing (ADN, about two years) or a bachelor of science in nursing (BSN, about four years) from a state-approved program, then you must pass the NCLEX-RN. Many hospitals prefer or require a BSN, and RN-to-BSN programs let ADN nurses complete a bachelor’s while working.",
  eduLevel: 3, train: "2–4 years", months: 24,
  degreeA: "Yes. You need at least an associate degree in nursing (ADN) or a bachelor’s (BSN) and must pass the NCLEX-RN. BLS lists a bachelor’s as the typical entry-level education, and many hospitals prefer BSN-prepared nurses.",
  certs: [["NCLEX-RN license", "Required in every state; issued by the state board of nursing after you pass the NCLEX-RN."], ["BLS, ACLS and PALS", "Life-support certifications from the American Heart Association, required in many units."], ["Specialty certifications", "Such as CCRN (critical care), CEN (emergency), CMSRN (medical-surgical) and PCCN (progressive care)."], ["Nurse Licensure Compact", "A multistate license lets RNs practice in participating states without separate licenses."]],
  license: "All states require RNs to be licensed by the state board of nursing after passing the NCLEX-RN. Many states participate in the Nurse Licensure Compact, which allows practice across member states with one multistate license.",
  steps: [["Complete prerequisites", "Most nursing programs require courses such as anatomy and physiology, microbiology, chemistry and statistics, plus an entrance exam such as the TEAS or HESI."], ["Earn an ADN or BSN", "Choose a state-approved, accredited program. ADN programs take about two years; BSN programs about four. Accelerated BSN options exist for people with a prior bachelor’s degree."], ["Pass the NCLEX-RN", "Apply to your state board of nursing, complete a background check and pass the national licensing exam."], ["Land your first nursing job", "New-graduate residency programs at hospitals provide structured orientation and mentoring in your first year."], ["Specialize and advance", "Earn specialty certifications, complete a BSN or MSN and consider roles such as charge nurse, educator, manager or nurse practitioner."]],
  riasec: "SIC", traits: ["helping", "people", "hands-on", "indoors", "fast-paced", "high-responsibility", "shift-work", "team", "problem-solving"],
  fit: ["I want a career where I make a real difference in people’s health", "I can stay calm and think clearly in emergencies", "I’m willing to complete two to four years of rigorous study", "I can handle long shifts on my feet", "I’m comfortable with science, math and medications", "I can cope with illness, suffering and death"],
  terms: [["NCLEX-RN", "The National Council Licensure Examination that registered nurses must pass to become licensed."], ["Nursing process (ADPIE)", "Assessment, Diagnosis, Planning, Implementation and Evaluation — the framework for nursing care."], ["Head-to-toe assessment", "A systematic physical assessment of every body system."], ["SBAR", "Situation, Background, Assessment, Recommendation — a structured way to communicate with providers."], ["Handoff report", "The transfer of patient information and responsibility between nurses, often at the bedside."], ["Rapid response", "A team called to the bedside when a patient shows early signs of deterioration."], ["Code blue", "An alert for a patient in cardiac or respiratory arrest."], ["Telemetry", "Continuous remote monitoring of a patient’s heart rhythm."], ["Titrate", "Adjusting a medication dose up or down to achieve a target effect."], ["Medication reconciliation", "Comparing a patient’s medication list at transitions in care to prevent errors."], ["Teach-back", "Asking patients to explain instructions in their own words to confirm understanding."], ["Sepsis", "A life-threatening response to infection that requires rapid recognition and treatment."], ["Intake and output (I&O)", "Measurement of all fluids a patient takes in and puts out."], ["Delegation", "Assigning tasks to LPNs or nursing assistants while remaining accountable for the outcome."], ["Scope of practice", "The services a nurse is legally allowed to perform, defined by the state nurse practice act."]],
  howto: [
    { t: "Perform a Head-to-Toe Nursing Assessment", intro: "A systematic head-to-toe assessment helps nurses establish a baseline and catch changes early.", steps: ["Perform hand hygiene, introduce yourself, confirm identity with two identifiers and explain the assessment.", "Note general appearance, level of consciousness and orientation to person, place, time and situation.", "Take vital signs, including pain and oxygen saturation.", "Assess head and neck, then the cardiovascular system: heart sounds, peripheral pulses, capillary refill and edema.", "Assess the respiratory system: rate, effort and lung sounds in all fields, front and back.", "Assess the abdomen (bowel sounds, tenderness, last bowel movement) and genitourinary status.", "Check skin integrity, IV sites, wounds and drains, then mobility, strength and fall risk; document findings and report abnormalities."], tip: "Always compare with the previous shift’s findings. A change from baseline matters more than a single abnormal number." },
    { t: "Hang an IV Piggyback Medication", intro: "Secondary (piggyback) infusions are a routine way to give intermittent IV medications such as antibiotics.", steps: ["Verify the order, check allergies and compatibility with the primary infusion and perform the medication rights.", "Scan the patient’s wristband and the medication with the barcode system.", "Spike the secondary bag with secondary tubing and prime it, removing air.", "Clean the upper port on the primary line and connect the secondary tubing.", "Hang the secondary bag higher than the primary bag (use the extension hook on the primary).", "Program the pump for the secondary infusion rate and volume and start it, confirming flow.", "Monitor for reactions, document the administration and remove or label tubing per policy."], tip: "Check that the primary line’s clamp configuration matches your pump — some pumps require the primary to stay unclamped for back-check valves to work." },
    { t: "Call a Provider Using SBAR", intro: "Clear, concise communication gets patients the right care faster.", steps: ["Before calling, assess the patient, review the chart, recent labs, vital signs, medications and allergies.", "Situation: “This is the RN caring for Mr. Diaz in room 412. I’m calling because his oxygen saturation dropped to 88% on 2 liters.”", "Background: diagnosis, admission date, relevant history and current treatment.", "Assessment: your findings and what you think is happening — “His lung sounds have new crackles; I’m concerned about fluid overload.”", "Recommendation: what you need — “I’d like you to evaluate him; would you like a chest X-ray and a dose of furosemide?”", "Read back the orders, carry them out and document the call and response."], tip: "If you don’t get the response your patient needs, follow your facility’s chain of command — patient safety comes first." }
  ],
  safety: ["Use barcode scanning and the rights of medication administration for every dose", "Follow standard and transmission-based precautions and wear appropriate PPE", "Use safe patient-handling equipment to prevent back injuries", "Speak up and escalate concerns through the chain of command"],
  iq: [["Tell me about a time you recognized a patient’s condition was getting worse.", "Use STAR: describe what you noticed, how you assessed and escalated (often via SBAR or rapid response) and the outcome. They want early recognition and action."], ["How do you prioritize when several patients need you at once?", "Explain ABCs, safety and time-critical meds first, delegation of appropriate tasks and communication with the team."], ["How would you handle a disagreement with a physician’s order?", "Clarify the order respectfully, share your concerns with data, consult the chain of command if needed and never carry out an order you believe is unsafe."], ["How do you support a family receiving bad news?", "Talk about presence, plain language, listening, involving chaplains or social work and respecting cultural needs."], ["Why this specialty and this hospital?", "Connect your clinical rotations and interests to the unit’s patient population and the organization’s values."]],
  faq: [["What’s the difference between an ADN and a BSN?", "Both prepare you to take the NCLEX-RN. A BSN is a four-year degree with more coursework in leadership, research and public health; many hospitals prefer or require it for hiring or advancement."], ["How long does it take to become an RN?", "About two years for an ADN or four years for a BSN, plus a few months to take the NCLEX-RN. Accelerated BSN programs for people with a prior bachelor’s can take 12 to 18 months."], ["What can RNs do after a few years?", "Specialize (ICU, ER, OR, labor and delivery), move into education, management or informatics, or earn a graduate degree to become a nurse practitioner, nurse anesthetist or clinical nurse specialist."]],
  quiz: [["In SBAR, what does the “R” stand for?", ["Report", "Recommendation", "Response", "Review"], 1, "SBAR ends with your Recommendation — what you think the patient needs."], ["Which exam must registered nurses pass to be licensed?", ["NCLEX-PN", "NCLEX-RN", "HESI", "TEAS"], 1, "The NCLEX-RN is the licensing exam for registered nurses."], ["What is the purpose of teach-back?", ["To test nurses’ knowledge", "To confirm a patient understands instructions", "To report to the next shift", "To check medication allergies"], 1, "Teach-back has patients explain instructions in their own words."], ["In the nursing process, which step comes first?", ["Planning", "Implementation", "Assessment", "Evaluation"], 2, "ADPIE begins with Assessment."], ["A rapid response team is called when:", ["A patient is ready for discharge", "A patient shows early signs of deterioration", "Shift change begins", "A medication is unavailable"], 1, "Rapid response teams intervene early, before a full arrest."]],
  path: [["Registered Nurse", "Deliver and coordinate patient care."], ["Charge Nurse or Specialty RN", "Lead a shift or specialize in ICU, ER, OR or pediatrics."], ["Nurse Educator, Manager or Case Manager", "Move into teaching, leadership or care coordination."], ["Advanced Practice RN", "Earn an MSN or DNP to become a nurse practitioner, CRNA or clinical nurse specialist."]],
  related: ["licensed-practical-nurse", "certified-nursing-assistant", "surgical-technologist", "emt"]
},
{
  slug: "emt", title: "Emergency Medical Technician", short: "EMT", cat: "healthcare",
  aka: ["EMT", "EMT-Basic", "Ambulance EMT", "Emergency Medical Responder"],
  blurb: "Respond to 911 calls, assess and treat patients and transport them safely.",
  summary: "Emergency medical technicians (EMTs) respond to 911 calls and emergencies, assess patients, provide basic life support such as CPR, bleeding control and oxygen, and safely transport patients to the hospital.",
  overview: [
    "EMTs are often the first medical professionals to reach a patient. They size up the scene for safety, assess airway, breathing and circulation, control bleeding, give oxygen, use automated external defibrillators (AEDs), immobilize injuries and assist with certain medications — then transport the patient while monitoring and reporting to the receiving hospital.",
    "The EMT course is relatively short — typically one to six months — and leads to certification through the National Registry of Emergency Medical Technicians (NREMT) and a state license. Many EMTs go on to become paramedics, firefighters, nurses or physician assistants."
  ],
  duties: ["Respond to 911 calls and assess scene safety", "Perform patient assessments and take vital signs", "Provide CPR, AED use, oxygen therapy and airway management", "Control bleeding, bandage wounds and splint fractures", "Assist patients with certain medications within EMT scope", "Safely lift, move and transport patients", "Document care in a patient care report and hand off to hospital staff"],
  day: [["6:00 AM", "Start a 24-hour shift: check the ambulance, oxygen levels, AED, suction and every compartment against the inventory list."], ["8:15 AM", "Respond to an older adult who fell at home; assess for injuries, take vitals and transport for evaluation."], ["10:30 AM", "Clean and restock the ambulance and complete the patient care report."], ["1:00 PM", "Respond to a motor-vehicle crash: triage two patients, apply a tourniquet and assist the paramedic."], ["4:00 PM", "Attend station training on airway skills and multiple-casualty incidents."], ["9:30 PM", "Transport a patient with chest pain, giving aspirin per protocol and calling a report to the emergency department."], ["2:00 AM", "Respond to a diabetic emergency; check blood glucose and give oral glucose to a conscious patient."]],
  env: "EMTs work for private ambulance companies, fire departments, hospitals and government agencies. Work happens in ambulances, homes, roadsides and public places in all weather. The job involves heavy lifting, kneeling and exposure to infectious disease and traumatic scenes.",
  schedule: "Shifts vary widely: 8, 12 or 24 hours, including nights, weekends and holidays. Many fire-based EMS agencies use 24-on/48-off schedules.",
  pros: ["Short training — start working in months", "Exciting, meaningful work every shift", "Excellent foundation for paramedic, nursing, fire or PA careers", "Strong teamwork culture"],
  cons: ["Entry-level pay is modest", "Physically demanding with injury risk", "Exposure to trauma, violence and stressful scenes", "Long and irregular shifts"],
  hard: ["Patient assessment", "CPR and AED use", "Airway management and oxygen therapy", "Bleeding control and splinting", "Safe lifting and patient movement", "Patient care report documentation"],
  soft: ["Calm under pressure", "Clear, reassuring communication", "Teamwork", "Quick decision-making"],
  tools: ["Automated external defibrillator (AED)", "Bag-valve mask (BVM) and oropharyngeal airways", "Oxygen cylinders and nonrebreather masks", "Stretchers and stair chairs", "Tourniquets and trauma dressings", "Electronic patient care reporting (ePCR) software"],
  edu: "You need a high school diploma or GED, a current CPR/BLS card and completion of a state-approved EMT course (often around 150–200 hours). After the course you pass the NREMT cognitive exam and a psychomotor skills exam, then apply for a state license.",
  eduLevel: 2, train: "1–6 months", months: 3,
  certs: [["NREMT EMT certification", "National certification from the National Registry of Emergency Medical Technicians, used for licensing in most states."], ["State EMT license", "Required to practice; issued by your state EMS office."], ["BLS for Healthcare Providers", "CPR certification required before and during EMT practice."], ["Advanced EMT and Paramedic", "Higher levels of certification with broader skills such as IV therapy and cardiac monitoring."]],
  license: "Every state licenses EMTs, and most use the NREMT exam for initial certification. Licenses must be renewed with continuing education, typically every two years.",
  steps: [["Meet basic requirements", "Be at least 18 (some courses accept 16–17), have a high school diploma or GED, a driver’s license and a clean background."], ["Get CPR certified", "Most EMT programs require a BLS for Healthcare Providers card before or during the course."], ["Complete a state-approved EMT course", "Courses include classroom learning, skills labs and clinical or ambulance ride-along hours."], ["Pass the NREMT exams and get licensed", "Pass the cognitive and psychomotor exams, then apply for your state license."], ["Start working and keep climbing", "Many EMTs gain experience, then pursue Advanced EMT or paramedic training."]],
  riasec: "SRI", traits: ["helping", "people", "hands-on", "physical", "fast-paced", "shift-work", "team", "high-responsibility", "outdoors"],
  fit: ["I stay calm and focused in emergencies", "I can lift and carry heavy weight with a partner", "Blood, injuries and illness don’t make me freeze", "I can handle long, unpredictable shifts", "I like fast-paced teamwork", "I want a quick path into healthcare or public safety"],
  terms: [["NREMT", "National Registry of Emergency Medical Technicians — the national certification body for EMS."], ["Scene size-up", "Assessing scene safety, mechanism of injury, number of patients and resources needed before patient contact."], ["Primary assessment", "A rapid check for life threats, often summarized as airway, breathing and circulation (ABC or XABC)."], ["SAMPLE history", "Signs/symptoms, Allergies, Medications, Past history, Last oral intake, Events leading up."], ["OPQRST", "Onset, Provocation, Quality, Region/Radiation, Severity, Time — used to assess pain."], ["AED", "Automated external defibrillator — analyzes heart rhythm and delivers a shock if needed."], ["BVM", "Bag-valve mask — used to ventilate patients who are not breathing adequately."], ["Mechanism of injury (MOI)", "The forces that caused an injury, used to predict likely injuries."], ["Shock (hypoperfusion)", "Inadequate blood flow to organs; signs include rapid pulse, pale clammy skin and confusion."], ["Triage (START)", "Simple Triage and Rapid Treatment — sorting multiple patients by urgency."], ["Medical direction", "Physician oversight of EMS care through protocols (offline) or radio/phone (online)."], ["Patient care report (PCR)", "The legal record of assessment, treatment and transport."], ["Glasgow Coma Scale (GCS)", "A 3–15 score of eye, verbal and motor response used to assess level of consciousness."], ["Spinal motion restriction", "Limiting movement of the spine in patients with suspected spinal injury."], ["Standard precautions", "Using gloves, eye protection and other PPE to prevent exposure to body fluids."]],
  howto: [
    { t: "Perform a Primary Assessment on a Trauma Patient", intro: "The primary assessment finds and fixes immediate life threats. Follow your local protocols.", steps: ["Ensure scene safety and put on PPE; note the mechanism of injury and call for additional resources if needed.", "Form a general impression and check responsiveness (AVPU: alert, verbal, pain, unresponsive).", "Control major external bleeding immediately with direct pressure or a tourniquet.", "Open and assess the airway, using a jaw-thrust if spinal injury is suspected.", "Assess breathing rate and quality; provide oxygen or BVM ventilations as indicated.", "Assess circulation: pulse, skin color, temperature and condition, and signs of shock.", "Decide on transport priority, then move to a rapid trauma assessment and vital signs."], tip: "Treat life threats as you find them. Don’t move on to the next step while a patient is bleeding heavily or not breathing." },
    { t: "Use an AED During CPR", intro: "Early defibrillation dramatically improves survival from sudden cardiac arrest.", steps: ["Confirm unresponsiveness and no normal breathing, call for help and start high-quality chest compressions.", "Turn on the AED as soon as it arrives and follow the voice prompts.", "Expose the chest, wipe it dry and attach the pads in the pictured positions.", "Make sure no one is touching the patient while the AED analyzes the rhythm.", "If a shock is advised, state “Clear!”, confirm no one is touching the patient and press the shock button.", "Immediately resume CPR for two minutes, then let the AED re-analyze; continue until advanced care takes over."], tip: "Minimize pauses in compressions. Every second without compressions reduces blood flow to the brain and heart." },
    { t: "Apply a Tourniquet", intro: "Tourniquets stop life-threatening bleeding from an arm or leg when direct pressure isn’t enough.", steps: ["Identify severe, life-threatening bleeding from an extremity.", "Place the tourniquet two to three inches above the wound — not over a joint.", "Pull the strap tight and secure it.", "Twist the windlass until the bleeding stops and the distal pulse is absent.", "Lock the windlass in place and secure it.", "Write the time of application on the tourniquet or patient.", "Do not loosen it; reassess and report the application time to the receiving hospital."], tip: "Tourniquet application hurts. Tell the patient it will be painful and that it is helping save their life." }
  ],
  safety: ["Always size up the scene and wait for law enforcement when a scene isn’t safe", "Wear gloves and eye protection for every patient contact", "Use proper lifting technique and lift with your partner", "Drive the ambulance with due regard for others — emergency status doesn’t remove responsibility"],
  iq: [["Why do you want to work in EMS?", "Give a sincere reason and show you understand the realities: long shifts, difficult calls and the importance of teamwork."], ["Walk me through your assessment of an unresponsive patient.", "Describe scene safety, PPE, checking responsiveness and breathing, starting CPR, using the AED and calling for advanced life support."], ["How do you handle a combative or intoxicated patient?", "Talk about scene safety, de-escalation, involving law enforcement if needed and protecting both patient and crew."], ["How do you cope with stressful calls?", "Mention healthy habits, peer support, debriefing and using employee assistance resources."], ["Tell me about a time you worked well on a team.", "Use a specific example and highlight clear communication, following direction and supporting your partner."]],
  faq: [["How long is EMT training?", "Most EMT courses take one to six months depending on the schedule, typically totaling around 150 to 200 hours of classroom, lab and clinical experience."], ["What’s the difference between an EMT and a paramedic?", "Paramedics complete much longer training (often 1,200 to 1,800 hours) and can perform advanced skills such as IV therapy, cardiac monitoring, advanced airways and giving many more medications."], ["Do EMTs need to be physically fit?", "Yes. EMTs lift and carry patients and equipment, often in difficult conditions, so strength, stamina and good body mechanics matter."]],
  quiz: [["What does the “S” in SAMPLE history stand for?", ["Severity", "Signs and symptoms", "Shock", "Scene"], 1, "SAMPLE starts with Signs and symptoms."], ["What should you do immediately after an AED delivers a shock?", ["Check a pulse for one minute", "Resume chest compressions", "Remove the pads", "Turn off the AED"], 1, "Resume CPR immediately for two minutes before the next analysis."], ["Where should a tourniquet be placed?", ["Directly over the wound", "Over the nearest joint", "Two to three inches above the wound, not over a joint", "Below the wound"], 2, "Place it proximal to the wound, avoiding joints."], ["A patient with pale, cool, clammy skin and a rapid pulse may be in:", ["Shock", "Hypertension", "Fever", "Normal condition"], 0, "These are classic signs of shock (hypoperfusion)."], ["What is the first step on every call?", ["Check the airway", "Scene size-up and safety", "Take vital signs", "Load the patient"], 1, "Scene safety comes first — an injured EMT can’t help anyone."]],
  path: [["EMT", "Provide basic life support and transport."], ["Advanced EMT", "Add IV access and additional medications."], ["Paramedic", "Provide advanced life support and lead calls."], ["Flight Medic, Supervisor, Firefighter or Nurse", "Specialize, lead or move into related careers."]],
  related: ["firefighter", "registered-nurse", "phlebotomist", "police-officer"]
},
{
  slug: "dental-assistant", title: "Dental Assistant", cat: "healthcare",
  aka: ["Certified Dental Assistant (CDA)", "Registered Dental Assistant (RDA)", "Chairside Assistant"],
  blurb: "Prepare patients, assist the dentist chairside, take X-rays and sterilize instruments.",
  summary: "Dental assistants prepare patients and treatment rooms, hand instruments and suction during procedures, take dental X-rays, sterilize instruments, and handle records and scheduling in dental offices.",
  overview: [
    "Dental assistants keep the dental office running smoothly and safely. They seat patients, review health histories, pass instruments during procedures using four-handed dentistry, keep the mouth clear with suction, mix materials, expose and process radiographs, and teach patients about oral hygiene.",
    "Requirements vary a lot by state. Some states allow on-the-job training, while others require a formal program, radiography certification or registration — especially for expanded functions such as placing sealants or polishing. Most programs take nine to twelve months."
  ],
  duties: ["Prepare treatment rooms and seat patients", "Review medical histories and take vital signs", "Pass instruments and use suction during procedures", "Take and process dental radiographs (X-rays) where certified", "Clean and sterilize instruments and maintain infection control", "Mix dental materials and take impressions as allowed by state law", "Give post-procedure and oral hygiene instructions; schedule appointments"],
  day: [["7:30 AM", "Run sterilizer spore-test records, set up operatories and review the day’s schedule with the dentist."], ["8:00 AM", "Seat the first patient, update their health history and take bitewing X-rays."], ["9:00 AM", "Assist with a two-surface composite filling: pass instruments, retract, suction and cure the material."], ["11:00 AM", "Break down the room, process instruments through ultrasonic cleaning and the autoclave and disinfect surfaces."], ["1:00 PM", "Take preliminary impressions for a mouthguard and pour models in the lab."], ["2:30 PM", "Assist with a crown preparation and fabricate a temporary crown."], ["4:30 PM", "Give a patient aftercare instructions and schedule their follow-up."]],
  env: "Nearly all dental assistants work in dentists’ offices; some work in specialty practices such as orthodontics or oral surgery, public health clinics or dental schools. Work is indoors, with frequent close patient contact. PPE such as gloves, masks and eyewear is worn throughout the day.",
  schedule: "Mostly full-time weekday hours, sometimes with evenings or Saturdays to fit patient schedules.",
  pros: ["Short training path and steady demand", "Predictable daytime hours in most offices", "Hands-on, patient-centered work", "Options to specialize or move into hygiene or office management"],
  cons: ["Repetitive tasks and long periods in fixed positions", "Exposure to bodily fluids and radiation requires strict safety", "Scope varies by state, which can limit duties", "Pay growth is limited without expanded functions or further education"],
  hard: ["Chairside assisting (four-handed dentistry)", "Dental radiography", "Infection control and sterilization", "Dental terminology and tooth numbering", "Impressions and dental materials", "Dental practice software"],
  soft: ["Putting nervous patients at ease", "Anticipating the dentist’s needs", "Attention to detail", "Teamwork"],
  tools: ["High-volume evacuator (HVE) and saliva ejector", "Air/water syringe", "Digital radiography sensors and X-ray units", "Autoclave and ultrasonic cleaner", "Curing light", "Practice management software such as Dentrix or Eaglesoft"],
  edu: "Many dental assistants complete a nine- to twelve-month certificate program at a community college or technical school. Some states allow on-the-job training, but most require radiography certification before you take X-rays, and some require registration or licensure for expanded duties.",
  eduLevel: 2, train: "9–12 months", months: 9,
  certs: [["CDA (DANB)", "Certified Dental Assistant from the Dental Assisting National Board, covering general chairside, radiation health and safety, and infection control."], ["RHS and ICE (DANB)", "Radiation Health and Safety and Infection Control exams, often used to meet state requirements."], ["State radiography or RDA credential", "Many states require specific certification or registration to take X-rays or perform expanded functions."], ["CPR / BLS", "Required by most employers."]],
  license: "Each state’s dental board sets rules for dental assistants. Requirements range from none to formal education, exams and registration, and expanded functions usually require additional credentials.",
  steps: [["Finish high school", "Biology, chemistry and health classes are helpful."], ["Complete a dental assisting program", "Look for programs accredited by the Commission on Dental Accreditation (CODA) for the broadest eligibility."], ["Earn required state credentials", "Pass radiography and infection-control exams and register with your state if required."], ["Earn the CDA", "National certification can raise pay and open doors in states that require it for expanded duties."], ["Specialize or advance", "Move into orthodontic, oral surgery or expanded-function roles, office management or dental hygiene school."]],
  riasec: "SCR", traits: ["people", "helping", "hands-on", "indoors", "team", "steady"],
  fit: ["I’m comfortable working closely in someone’s personal space", "I can stay focused on precise, detailed tasks", "I like predictable daytime hours", "I can follow strict infection-control routines", "I enjoy helping nervous people relax", "I want a healthcare career I can start within a year"],
  terms: [["Four-handed dentistry", "A technique where the dentist and assistant work together efficiently, passing instruments in a coordinated way."], ["High-volume evacuator (HVE)", "A large suction tip used to remove fluids and debris during procedures."], ["Universal Numbering System", "The U.S. system numbering adult teeth 1–32, starting with the upper right third molar."], ["Mesial", "The tooth surface closest to the midline of the dental arch."], ["Distal", "The tooth surface farthest from the midline."], ["Occlusal", "The chewing surface of back teeth."], ["Bitewing radiograph", "An X-ray showing upper and lower back teeth together, used to detect decay between teeth."], ["Prophylaxis", "Professional cleaning to remove plaque and calculus."], ["Composite", "A tooth-colored filling material cured with a special light."], ["Alginate", "An impression material used for study models and mouthguards."], ["Dental dam", "A thin sheet that isolates teeth during procedures to keep them dry."], ["Autoclave", "A steam sterilizer used to kill microorganisms on instruments."], ["Spore test", "A biological indicator test that confirms the sterilizer is working."], ["Sealant", "A protective coating placed on chewing surfaces to prevent decay."], ["Periodontal charting", "Recording gum pocket depths and other measures of gum health."]],
  howto: [
    { t: "Process and Sterilize Dental Instruments", intro: "Instrument processing protects patients and staff. Follow CDC guidance and your office’s protocol.", steps: ["Wear utility gloves, mask, eyewear and a gown when handling contaminated instruments.", "Transport instruments to the sterilization area in a closed, labeled container.", "Clean instruments in an ultrasonic cleaner or instrument washer — avoid hand scrubbing when possible.", "Rinse, dry and inspect for remaining debris or damage.", "Package instruments in sterilization pouches or wrapped cassettes with a chemical indicator.", "Run the autoclave cycle according to the manufacturer’s instructions and let packages dry.", "Store packages in a clean, dry area and log the cycle; run weekly biological spore tests."], tip: "Never open a sterilized package until you are ready to use it chairside — the patient should see it opened." },
    { t: "Take Bitewing X-Rays", intro: "Bitewings help dentists find decay between teeth. Only take radiographs if you are properly certified in your state.", steps: ["Review the dentist’s prescription and the patient’s health history; ask about pregnancy per office policy.", "Place a lead or lead-equivalent apron with thyroid collar on the patient, if your office uses one.", "Seat the patient upright with the occlusal plane parallel to the floor.", "Position the sensor or film holder so it captures the distal of the canine through the molars.", "Have the patient bite gently, align the X-ray cone with the positioning ring and expose.", "Repeat for the other side and any additional views ordered.", "Review the images for diagnostic quality, retake only if the dentist approves and document."], tip: "Follow the ALARA principle — keep radiation exposure As Low As Reasonably Achievable." },
    { t: "Prepare an Operatory for the Next Patient", intro: "Room turnover between patients is one of the most important infection-control routines in dentistry.", steps: ["Wearing PPE, remove used instruments and dispose of sharps and single-use items properly.", "Flush handpieces and waterlines per manufacturer instructions.", "Clean and disinfect all touched surfaces with an EPA-registered disinfectant, following the contact time.", "Place new barriers on high-touch surfaces such as light handles and keyboards.", "Set out sterile instrument packages and supplies for the scheduled procedure.", "Review the next patient’s chart and health history before seating them."], tip: "Barriers save time, but they only work if you change them between every patient." }
  ],
  safety: ["Follow CDC infection-control guidance and OSHA’s Bloodborne Pathogens Standard", "Use proper radiation safety and never hold sensors for patients during exposures", "Wear gloves, masks and eye protection for every procedure", "Handle sharps carefully and dispose of them immediately"],
  iq: [["How do you help an anxious patient feel comfortable?", "Describe explaining steps, checking in often, using a calm voice and alerting the dentist about anxiety. Empathy plus professionalism is key."], ["Walk me through how you turn over an operatory.", "List PPE, disposal, disinfection with proper contact time, barriers and setup. This shows you know infection control."], ["Are you certified to take radiographs in this state?", "Answer directly and explain your training and any state credential you hold."], ["How do you anticipate the dentist’s needs during a procedure?", "Talk about knowing procedure sequences, tray setups and watching for cues."], ["What would you do if you were exposed to a needlestick?", "Wash the area, report it immediately and follow the office’s post-exposure plan."]],
  faq: [["Do dental assistants need to be certified?", "It depends on the state. Some states allow on-the-job training, while others require formal education, exams or registration — especially to take X-rays or perform expanded functions."], ["What’s the difference between a dental assistant and a dental hygienist?", "Dental hygienists complete an associate degree or higher, are licensed, and clean teeth and assess gum health. Dental assistants support the dentist and office, with duties set by state law."], ["Can dental assistants work in orthodontics?", "Yes. Orthodontic assistants help with braces, aligners, impressions and patient education, and duties vary by state."]],
  quiz: [["In the Universal Numbering System, adult teeth are numbered:", ["A–T", "1–20", "1–32", "11–48"], 2, "The Universal system numbers permanent teeth 1–32."], ["What does a spore test check?", ["Water quality", "That the sterilizer is killing microorganisms", "X-ray machine output", "Patient allergies"], 1, "Biological indicators confirm sterilization effectiveness."], ["The surface of a tooth closest to the midline is called:", ["Distal", "Mesial", "Occlusal", "Lingual"], 1, "Mesial is toward the midline."], ["ALARA in radiography means:", ["Always Lead Apron, Right Angle", "As Low As Reasonably Achievable", "All Lights Are Required Always", "Align, Load, Aim, Release, Archive"], 1, "Keep radiation exposure as low as reasonably achievable."], ["Which tool removes fluids and debris during procedures?", ["Curing light", "High-volume evacuator", "Autoclave", "Explorer"], 1, "The HVE is the large suction used chairside."]],
  path: [["Dental Assistant", "Assist chairside and keep the office safe."], ["Expanded-Function or Specialty Assistant", "Add duties such as sealants or coronal polishing, or specialize in ortho or oral surgery."], ["Lead Assistant or Office Manager", "Train staff and manage operations."], ["Dental Hygienist or Practice Administrator", "Pursue licensure in hygiene or move into practice management."]],
  related: ["medical-assistant", "pharmacy-technician", "medical-billing-and-coding-specialist", "phlebotomist"]
},
{
  slug: "medical-billing-and-coding-specialist", title: "Medical Billing and Coding Specialist", short: "Medical Coder", cat: "healthcare",
  aka: ["Medical Coder", "Medical Biller", "Coding Specialist", "Medical Records Specialist"],
  blurb: "Translate medical records into codes and claims so providers get paid correctly.",
  summary: "Medical billing and coding specialists review patient records, assign standardized diagnosis and procedure codes (ICD-10-CM, CPT and HCPCS), submit insurance claims, and follow up on denials so healthcare providers are paid accurately.",
  overview: [
    "Every doctor visit, lab test and surgery has to be translated into codes before anyone gets paid. Medical coders read clinical documentation and assign diagnosis and procedure codes; medical billers turn those codes into claims, submit them to insurers and follow up until they’re paid. Many professionals do both.",
    "It is detail-oriented, behind-the-scenes healthcare work with no patient contact, and many experienced coders work remotely. Most people train through a certificate program of several months to a year and earn a credential such as the CPC or CCA."
  ],
  duties: ["Review physician notes, operative reports and other documentation", "Assign ICD-10-CM diagnosis codes and CPT/HCPCS procedure codes", "Apply modifiers and check codes against payer and NCCI edits", "Prepare and submit claims electronically through a clearinghouse", "Post payments and review explanations of benefits", "Investigate and appeal denied or underpaid claims", "Query providers when documentation is unclear and protect patient privacy"],
  day: [["8:00 AM", "Log into the encoder and EHR from home and pull the queue of yesterday’s outpatient visits."], ["9:00 AM", "Code office visits, choosing the evaluation and management level supported by the documentation."], ["10:30 AM", "Send a provider query asking whether a diagnosis was acute or chronic."], ["12:30 PM", "Review the clearinghouse rejection report and fix a missing modifier and an invalid diagnosis pointer."], ["2:00 PM", "Work denials: appeal a medical-necessity denial with supporting documentation."], ["3:30 PM", "Post insurance payments from electronic remittance advice and flag underpayments."], ["4:30 PM", "Complete a coding education module on this year’s code updates."]],
  env: "Medical billers and coders work for hospitals, physician practices, billing companies, insurance companies and outsourcing firms. The work is computer-based and sedentary. Many experienced coders work remotely full time.",
  schedule: "Usually full-time weekday hours. Remote and flexible schedules are common once you have experience and meet productivity and accuracy standards.",
  pros: ["No patient contact or blood — healthcare from behind a desk", "Strong remote-work potential after experience", "Certificate programs take months, not years", "Clear certifications and specialties raise pay"],
  cons: ["Highly detail-oriented and repetitive", "Productivity and accuracy quotas", "Annual code changes require continual learning", "Entry-level coding jobs often require experience — billing can be the door in"],
  hard: ["ICD-10-CM diagnosis coding", "CPT and HCPCS Level II procedure coding", "Medical terminology and anatomy", "Claims submission and denial management", "Payer rules and modifiers", "HIPAA compliance"],
  soft: ["Attention to detail", "Analytical thinking", "Self-discipline for remote work", "Clear written communication with providers"],
  tools: ["Encoder software such as 3M or Optum EncoderPro", "EHR systems such as Epic or athenahealth", "Practice management and billing systems", "Claims clearinghouses", "ICD-10-CM, CPT and HCPCS code books", "Spreadsheets for tracking A/R and denials"],
  edu: "Most employers prefer a postsecondary certificate in medical billing and coding (several months to a year) or an associate degree in health information technology, plus a professional certification.",
  eduLevel: 2, train: "4–12 months", months: 6,
  certs: [["CPC (AAPC)", "Certified Professional Coder — the most common credential for physician-office coding."], ["CCA or CCS (AHIMA)", "Certified Coding Associate (entry level) and Certified Coding Specialist (hospital coding)."], ["CPB (AAPC)", "Certified Professional Biller for billing and reimbursement professionals."], ["RHIT (AHIMA)", "Registered Health Information Technician, requiring an accredited associate degree."]],
  steps: [["Finish high school or earn a GED", "Strong reading, computer and math skills help."], ["Complete a billing and coding program", "Study medical terminology, anatomy, ICD-10-CM, CPT, HCPCS, reimbursement and compliance."], ["Earn a certification", "Pass the CPC, CCA or CPB exam. Some credentials start as apprentice-level until you gain experience."], ["Get your first job", "Billing, registration, charge entry or payment posting roles are common ways to gain experience before full coding roles."], ["Specialize", "Add specialty credentials such as risk adjustment (CRC), inpatient coding (CCS) or auditing to raise pay."]],
  riasec: "CIR", traits: ["data", "desk", "indoors", "independent", "remote-friendly", "steady", "problem-solving"],
  fit: ["I enjoy detailed, accurate work at a computer", "I want a healthcare job without patient contact", "I can stay focused and productive on my own", "I like learning rules and applying them precisely", "I’m interested in medical terms and how the body works", "Remote work in the future appeals to me"],
  terms: [["ICD-10-CM", "The diagnosis coding system used in the U.S. for all healthcare settings."], ["CPT", "Current Procedural Terminology — five-digit codes for medical services and procedures, maintained by the AMA."], ["HCPCS Level II", "Codes for supplies, equipment, drugs and services not in CPT, such as ambulance services."], ["Modifier", "A two-character code added to a CPT or HCPCS code to give more information, such as -25 or -59."], ["CMS-1500", "The standard claim form for professional (physician) services."], ["UB-04", "The standard claim form for institutional (facility) services."], ["Clearinghouse", "A company that checks and forwards electronic claims to insurers."], ["EOB / ERA", "Explanation of benefits / electronic remittance advice — the payer’s explanation of what was paid and why."], ["Denial", "A payer’s refusal to pay a claim, which may be corrected and resubmitted or appealed."], ["NCCI edits", "National Correct Coding Initiative rules that prevent improper code combinations."], ["Medical necessity", "Whether a service is reasonable and necessary for the patient’s diagnosis."], ["E/M coding", "Evaluation and management codes for office visits and other patient encounters."], ["Provider query", "A compliant question to a provider to clarify documentation."], ["Revenue cycle", "The full process from patient registration to final payment."], ["Accounts receivable (A/R)", "Money owed to the provider that has not yet been collected."]],
  howto: [
    { t: "Assign an ICD-10-CM Diagnosis Code", intro: "Correct diagnosis coding supports medical necessity and accurate payment.", steps: ["Read the entire encounter note and identify the condition(s) the provider documented as the reason for the visit.", "Look up the main term in the ICD-10-CM Alphabetic Index.", "Follow any subterms, notes and cross-references to a tentative code.", "Verify the code in the Tabular List — never code from the index alone.", "Check instructional notes such as Excludes1, Excludes2, “code first” and “use additional code.”", "Assign the code to the highest level of specificity (all required characters, including any seventh character).", "Sequence the first-listed diagnosis correctly and query the provider if documentation is unclear."], tip: "Only code what the provider documented. Never assume a diagnosis from a lab result or medication list." },
    { t: "Submit a Clean Claim", intro: "A clean claim is accepted and processed on the first submission — the fastest way to get paid.", steps: ["Verify the patient’s demographics and insurance eligibility before the visit.", "Confirm the provider’s documentation supports every code billed.", "Enter diagnosis codes, procedure codes, modifiers and diagnosis pointers correctly.", "Check the place of service, rendering provider NPI and dates of service.", "Run claim scrubber edits and fix any errors.", "Submit electronically through the clearinghouse and review the acceptance report."], tip: "Track your first-pass acceptance rate. Patterns in rejections point to fixable front-end problems." },
    { t: "Work a Denied Claim", intro: "Denials are lost revenue until someone fixes them. A systematic approach recovers money faster.", steps: ["Read the denial reason and remark codes on the EOB or ERA.", "Categorize the denial: registration error, coding error, missing authorization, medical necessity or timely filing.", "Check the payer’s policy for the service.", "Correct and resubmit if the claim had an error.", "If the claim was correct, write an appeal with supporting documentation within the payer’s deadline.", "Document every action in the account notes and track the outcome."], tip: "Fix the root cause, not just the claim. If one registration mistake causes 50 denials, the solution is upstream." }
  ],
  safety: ["Protect patient information under HIPAA — access only what you need for your job", "Never upcode or bill for services not documented; this can constitute fraud", "Lock your screen and secure your home workspace if remote", "Report suspected compliance problems through proper channels"],
  iq: [["How do you stay accurate when you have productivity goals?", "Explain your process: reading the full note, verifying in the Tabular List, using edits and checking your own error trends."], ["What would you do if a provider’s documentation doesn’t support the code they selected?", "Describe sending a compliant, non-leading query and coding only what is documented."], ["How do you keep up with code changes?", "Mention annual ICD-10-CM and CPT updates, CEUs, payer bulletins and professional associations."], ["Tell me about a denial you resolved.", "Use STAR to describe identifying the reason, fixing or appealing and the result."], ["How comfortable are you working remotely?", "Talk about your routine, workspace security, communication habits and meeting goals independently."]],
  faq: [["Can medical coders work from home?", "Many can, especially after gaining experience and certification. Employers often require a period of on-site work or a track record of accuracy first."], ["Is medical billing the same as medical coding?", "They’re related but different. Coders translate documentation into codes; billers use those codes to create claims, submit them and follow up on payment. Many jobs combine both."], ["Which certification is best for beginners?", "The CPC from AAPC is common for physician-office coding, while AHIMA’s CCA is an entry-level credential. Check local job postings to see what employers ask for."]],
  quiz: [["Which code set is used for diagnoses in the U.S.?", ["CPT", "HCPCS Level II", "ICD-10-CM", "NDC"], 2, "ICD-10-CM is the U.S. diagnosis code set."], ["Before assigning a code found in the Alphabetic Index, you should:", ["Submit the claim", "Verify it in the Tabular List", "Ask the patient", "Add a modifier"], 1, "Always verify codes in the Tabular List."], ["What is a clean claim?", ["A claim paid in cash", "A claim accepted and processed without errors on first submission", "A claim with no diagnosis", "A denied claim"], 1, "Clean claims process on the first pass."], ["The CMS-1500 form is used for:", ["Hospital inpatient services", "Professional (physician) services", "Pharmacy claims", "Dental claims"], 1, "CMS-1500 is the professional claim form."], ["Upcoding means:", ["Using the newest code set", "Billing a higher-level service than documented", "Adding a modifier", "Coding to the highest specificity"], 1, "Upcoding is billing for more than was documented and can be fraud."]],
  path: [["Medical Biller or Coder", "Code encounters and manage claims."], ["Certified Specialty Coder", "Specialize in areas such as risk adjustment, inpatient or surgical coding."], ["Coding Auditor or Revenue Cycle Analyst", "Audit accuracy and improve reimbursement."], ["Coding Manager or Compliance Officer", "Lead teams and oversee compliance programs."]],
  related: ["medical-assistant", "bookkeeper", "pharmacy-technician", "administrative-assistant"]
},
{
  slug: "surgical-technologist", title: "Surgical Technologist", short: "Surgical Tech", cat: "healthcare",
  aka: ["Surgical Tech", "Scrub Tech", "Operating Room Technician", "Certified Surgical Technologist (CST)"],
  blurb: "Prepare the operating room, keep the sterile field and pass instruments to surgeons.",
  summary: "Surgical technologists prepare operating rooms, set up sterile instruments and equipment, pass instruments and supplies to surgeons during procedures, and maintain the sterile field to protect patients from infection.",
  overview: [
    "Surgical technologists — often called scrub techs — are the guardians of the sterile field. Before surgery they gather and inspect instruments and supplies, scrub in, gown and glove, and arrange the back table and Mayo stand. During the operation they anticipate what the surgeon needs next, handle specimens and keep count of every sponge, sharp and instrument.",
    "Training usually happens through a certificate or associate degree program of one to two years that includes extensive clinical rotations in real operating rooms. Many employers require or prefer the Certified Surgical Technologist (CST) credential."
  ],
  duties: ["Prepare operating rooms with sterile instruments, equipment and supplies", "Perform surgical scrub and gown and glove themselves and the surgical team", "Set up and maintain the sterile field throughout the procedure", "Pass instruments, sutures and supplies to the surgeon, anticipating needs", "Perform counts of sponges, sharps and instruments with the circulator", "Handle and label surgical specimens", "Break down the field and send instruments for reprocessing"],
  day: [["6:30 AM", "Check the surgeon’s preference card, pull instrument trays and verify sterility indicators."], ["7:00 AM", "Scrub, gown and glove, open sterile supplies and organize the back table and Mayo stand."], ["7:30 AM", "Perform the initial count with the circulating nurse and participate in the surgical time out."], ["8:00 AM", "Assist in a laparoscopic gallbladder removal, passing instruments and managing the camera cords."], ["9:30 AM", "Perform closing counts, prepare sutures and dressings and hand off the specimen correctly labeled."], ["10:00 AM", "Break down the room and help turn it over for the next case — an orthopedic knee replacement."], ["2:30 PM", "Restock, clean up and review preference cards for tomorrow’s cases."]],
  env: "Most surgical technologists work in hospital operating rooms; others work in outpatient surgery centers and physicians’ offices that perform surgery. They stand for long periods, wear scrubs, masks and gowns, and must stay alert during long cases.",
  schedule: "Usually full-time. Hospitals require on-call coverage for emergency surgeries on nights, weekends and holidays; outpatient centers keep more regular daytime hours.",
  pros: ["Exciting, high-stakes teamwork in the OR", "Training in one to two years", "Good pay for the training time", "Opportunities to specialize in heart, neuro, ortho or other surgeries"],
  cons: ["Long periods of standing in one position", "On-call shifts for emergency cases", "High-pressure environment with little room for error", "Exposure to blood, fumes and sharp instruments"],
  hard: ["Aseptic technique and sterile field maintenance", "Surgical instrument identification", "Surgical counts", "Gowning and gloving", "Specimen handling", "Surgical anatomy and procedures"],
  soft: ["Anticipating needs", "Focus and stamina", "Calm under pressure", "Precise communication"],
  tools: ["Back table and Mayo stand setups", "Surgical instrument trays (retractors, hemostats, scissors, forceps)", "Electrosurgical units", "Suction and irrigation systems", "Laparoscopic towers and cameras", "Sterilization indicators and wrappers"],
  edu: "Most surgical technologists complete a postsecondary certificate (about 12 to 18 months) or an associate degree (about two years) from a program accredited by CAAHEP or ABHES, including supervised clinical cases.",
  eduLevel: 2, train: "12–24 months", months: 15,
  certs: [["CST (NBSTSA)", "Certified Surgical Technologist from the National Board of Surgical Technology and Surgical Assisting."], ["TS-C (NCCT)", "Tech in Surgery – Certified from the National Center for Competency Testing."], ["BLS / CPR", "Required by most employers."], ["CSFA", "Certified Surgical First Assistant — an advanced credential with additional training."]],
  license: "Several states require surgical technologists to be certified or registered. Many employers require the CST regardless of state rules.",
  steps: [["Finish high school", "Biology, anatomy and chemistry are helpful preparation."], ["Complete an accredited program", "Choose a CAAHEP- or ABHES-accredited certificate or associate program so you can sit for the CST exam."], ["Complete clinical cases", "Programs require a set number of supervised surgical cases in real operating rooms."], ["Pass the CST exam", "Earn certification and meet any state registration requirements."], ["Specialize and advance", "Specialize in a surgical service, become a lead tech or train as a surgical first assistant."]],
  riasec: "RSC", traits: ["hands-on", "helping", "indoors", "team", "fast-paced", "high-responsibility", "shift-work"],
  fit: ["I can stand and stay focused for hours at a time", "I’m fascinated by surgery and anatomy", "I can stay calm when things get tense", "I’m extremely careful about cleanliness and details", "I like working as part of a tight team", "I’m OK taking call for emergency surgeries"],
  terms: [["Sterile field", "The area around the patient and instruments kept free of microorganisms during surgery."], ["Scrub role", "The team member who works within the sterile field, passing instruments."], ["Circulator", "The non-sterile team member, usually an RN, who manages the room and supplies."], ["Back table", "The large sterile table where instruments and supplies are organized."], ["Mayo stand", "A small sterile tray positioned over the patient holding instruments in immediate use."], ["Surgical count", "A documented count of sponges, sharps and instruments to prevent retained items."], ["Time out", "A pause before incision to confirm patient, procedure, site and other safety checks."], ["Surgical conscience", "A personal commitment to report any break in sterile technique, even if no one saw it."], ["Closed gloving", "A technique for putting on sterile gloves without the hands leaving the gown sleeves."], ["Hemostat", "A clamp used to control bleeding."], ["Retractor", "An instrument used to hold tissue or organs aside."], ["Suture", "Thread used to close wounds or tie off vessels."], ["Electrosurgical unit (ESU)", "A device that uses electrical current to cut tissue and control bleeding."], ["Preference card", "A surgeon’s list of preferred instruments, supplies and setup for a procedure."], ["Specimen", "Tissue removed during surgery that is sent to pathology for examination."]],
  howto: [
    { t: "Perform a Surgical Hand Scrub", intro: "Surgical hand antisepsis reduces microorganisms on the skin before you enter the sterile field. Follow your facility’s policy and product instructions.", steps: ["Remove jewelry, check that nails are short and clean, and put on a surgical cap and mask.", "Wash hands and forearms with soap and water if visibly soiled, cleaning under nails with a nail cleaner.", "Apply the approved scrub agent and scrub each side of each finger, between fingers, the hands and forearms to two inches above the elbow.", "Keep hands above the elbows so water runs away from the hands.", "Follow the timed or counted-stroke method required by your facility.", "Rinse from fingertips to elbows, keeping hands up.", "Enter the OR backward through the door and dry with a sterile towel before gowning."], tip: "If your hands touch anything non-sterile during the scrub, start over. That’s surgical conscience." },
    { t: "Gown and Glove Using Closed Gloving", intro: "Closed gloving keeps your bare hands from ever touching the outside of the sterile gown or gloves.", steps: ["Pick up the folded sterile gown by the inside neckline and step back from the table.", "Let the gown unfold and slide your arms into the sleeves without pushing your hands through the cuffs.", "Have the circulator pull the gown on and tie the back.", "With your hand inside the sleeve, pick up the first glove and place it palm-down on the opposite sleeve.", "Grasp the glove cuff through the sleeve and pull it over the gown cuff, then work your hand into the glove.", "Repeat for the other hand and secure the gown’s outer tie with help from a sterile team member or the circulator.", "Keep hands at or above waist level and in front of you at all times."], tip: "The back of a sterile gown is considered non-sterile. Never turn your back to the sterile field." },
    { t: "Perform a Surgical Count", intro: "Counts prevent retained surgical items — one of the most serious preventable errors in surgery.", steps: ["Perform the initial count with the circulator before the incision, counting aloud and viewing each item together.", "Separate and count sponges one at a time, confirming each sponge’s radiopaque marker.", "Count sharps, needles and instruments per facility policy and record on the count board.", "Add any items opened during surgery to the count immediately.", "Count again before closing a cavity, before closing the skin and at any change of personnel.", "Report discrepancies immediately so the team can search and, if needed, obtain an X-ray."], tip: "Never leave a count unfinished because the case is running late. A correct count is non-negotiable." }
  ],
  safety: ["Maintain sterile technique and speak up about any break in sterility", "Pass sharps using a neutral zone or with clear communication", "Use smoke evacuation for electrosurgery to reduce exposure to surgical plume", "Follow counts and time-out protocols on every case"],
  iq: [["What would you do if you saw a surgeon contaminate the sterile field?", "Describe speaking up immediately and respectfully, explaining that surgical conscience requires it and patient safety comes first."], ["Walk me through how you set up for a common procedure.", "Describe checking the preference card, opening supplies, organizing the back table and Mayo stand and performing counts."], ["How do you handle a count discrepancy?", "Report it right away, help search the field and follow policy, including X-ray if needed."], ["How do you stay focused during long cases?", "Mention preparation, hydration, posture and anticipating steps of the procedure."], ["Which surgical specialties interest you most and why?", "Connect your clinical rotations to a specialty and show enthusiasm for learning more."]],
  faq: [["Is surgical tech school hard?", "It’s demanding — you’ll learn anatomy, microbiology, hundreds of instruments and sterile technique, and complete real surgical cases. Most programs take 12 to 24 months."], ["Do surgical technologists need certification?", "Some states require certification or registration, and many employers prefer or require the CST regardless of state law."], ["Can surgical techs become nurses or surgical assistants?", "Yes. Many surgical techs go on to nursing school or train as certified surgical first assistants."]],
  quiz: [["Who usually serves as the circulator?", ["The surgeon", "A non-sterile RN who manages the room", "The anesthesiologist", "The patient’s family"], 1, "The circulator is typically a registered nurse outside the sterile field."], ["When should surgical counts be performed?", ["Only at the end of the case", "Before incision, before closing and at personnel changes", "Only if something is missing", "Once per day"], 1, "Counts happen at defined points to prevent retained items."], ["Which part of a sterile gown is considered non-sterile?", ["The front from chest to waist", "The sleeves", "The back", "The cuffs"], 2, "The back of the gown can’t be monitored and is considered non-sterile."], ["“Surgical conscience” means:", ["Never speaking during surgery", "Reporting any break in sterile technique, even if unseen", "Following the surgeon’s orders without question", "Counting only sharps"], 1, "It’s a personal commitment to sterile technique."], ["A hemostat is used to:", ["Hold tissue aside", "Clamp vessels to control bleeding", "Cut sutures", "Measure blood loss"], 1, "Hemostats clamp vessels and tissue."]],
  path: [["Surgical Technologist", "Maintain the sterile field and assist the surgical team."], ["Specialty or Lead Surgical Tech", "Focus on cardiac, neuro or orthopedic surgery, or lead a team."], ["Certified Surgical First Assistant", "Assist directly with exposure, hemostasis and closure."], ["RN, OR Educator or Sterile Processing Manager", "Move into nursing, education or perioperative leadership."]],
  related: ["registered-nurse", "licensed-practical-nurse", "medical-assistant", "dental-assistant"]
}
];
